    public List<Discharge> testGetAll() throws Throwable {
    LOGGER.info( "DischargeTest:testGetAll() - Retrieving Collection of Discharges:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Discharge : " );
    List<Discharge> collection  = null;

    try {
        // call the static get method on the DischargeService
        collection = service.getAllDischarge();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Discharge currEntity  = null;
            Iterator<Discharge> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getDischargeId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

